package com.ejemplo.alquileres.service;

import com.ejemplo.alquileres.exception.NegocioException;
import com.ejemplo.alquileres.model.*;
import com.ejemplo.alquileres.repository.*;
import java.math.*;
import java.time.*;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @RequiredArgsConstructor
public class MantenimientoService {
 private final MantenimientoRepository mantenimientos; private final InmuebleRepository inmuebles; private final ContratoRepository contratos; private final CuotaRepository cuotas; private final SecuenciaService secuencias; private final Permisos permisos; private final Clock clock;
 public record Solicitud(Long inmuebleId,Long contratoId,LocalDate fechaReporte,String titulo,String descripcion,CategoriaMantenimiento categoria,PrioridadMantenimiento prioridad,ResponsablePago responsablePago,String tecnico,String telefonoTecnico,BigDecimal costoEstimado,LocalDate fechaProgramada,String observaciones){}
 public record Resumen(long abiertos,long urgentes,long enProceso,BigDecimal gastoMes){}
 public Page<Mantenimiento> listar(String texto,EstadoMantenimiento estado,PrioridadMantenimiento prioridad,Long inmuebleId,CategoriaMantenimiento categoria,int pagina,int tamano){return mantenimientos.buscar(texto==null?"":texto.trim(),estado,prioridad,inmuebleId,categoria,PageRequest.of(Math.max(0,pagina),tamano,Sort.by(Sort.Direction.DESC,"fechaReporte").and(Sort.by(Sort.Direction.DESC,"id"))));}
 public List<Mantenimiento> porInmueble(Long id){return mantenimientos.porInmueble(id);}
 public List<Mantenimiento> gastosPropietario(LocalDate desde,LocalDate hasta){return mantenimientos.gastosPropietario(desde,hasta);}
 public Resumen resumen(){LocalDate hoy=LocalDate.now(clock);BigDecimal gasto=mantenimientos.gastosPropietario(hoy.withDayOfMonth(1),hoy).stream().map(Mantenimiento::getCostoReal).reduce(BigDecimal.ZERO,BigDecimal::add);return new Resumen(mantenimientos.countByEstado(EstadoMantenimiento.REPORTADO),mantenimientos.countByEstadoAndPrioridad(EstadoMantenimiento.REPORTADO,PrioridadMantenimiento.URGENTE),mantenimientos.countByEstado(EstadoMantenimiento.EN_PROCESO),dinero(gasto));}
 @Transactional public Mantenimiento registrar(Solicitud s){permisos.exigirGestion();validarRegistro(s);Inmueble inmueble=inmueble(s.inmuebleId());Contrato contrato=s.contratoId()==null?contratoVigente(inmueble.getId()):contrato(s.contratoId());if(contrato!=null&&!contrato.getInmueble().getId().equals(inmueble.getId()))throw new NegocioException("El contrato debe pertenecer al inmueble.");Mantenimiento m=Mantenimiento.builder().codigo(secuencias.formatear("MNT-",secuencias.siguiente("MANTENIMIENTO"),6)).inmueble(inmueble).contrato(contrato).fechaReporte(s.fechaReporte()).titulo(s.titulo().trim()).descripcion(texto(s.descripcion())).categoria(s.categoria()).prioridad(s.prioridad()).responsablePago(s.responsablePago()==null?ResponsablePago.PROPIETARIO:s.responsablePago()).tecnico(texto(s.tecnico())).telefonoTecnico(texto(s.telefonoTecnico())).costoEstimado(dineroNulo(s.costoEstimado())).fechaProgramada(s.fechaProgramada()).observaciones(texto(s.observaciones())).fechaRegistro(LocalDate.now(clock)).build();return mantenimientos.save(m);}
 @Transactional public Mantenimiento iniciar(Long id,boolean ponerInmueble){permisos.exigirGestion();Mantenimiento m=obtener(id);exigir(m,EstadoMantenimiento.REPORTADO);if(ponerInmueble){if(m.getInmueble().getEstado()!=EstadoInmueble.DISPONIBLE)throw new NegocioException("Solo se puede poner en mantenimiento un inmueble disponible.");m.getInmueble().setEstado(EstadoInmueble.MANTENIMIENTO);m.setPusoInmuebleEnMantenimiento(true);}m.setEstado(EstadoMantenimiento.EN_PROCESO);return m;}
 @Transactional public Mantenimiento resolver(Long id,LocalDate fecha,BigDecimal costo){permisos.exigirGestion();Mantenimiento m=obtener(id);exigir(m,EstadoMantenimiento.EN_PROCESO);if(fecha==null||costo==null)throw new NegocioException("La fecha de resolución y el costo real son obligatorios.");if(fecha.isBefore(m.getFechaReporte())||fecha.isAfter(LocalDate.now(clock)))throw new NegocioException("La fecha de resolución debe estar entre el reporte y hoy.");if(costo.signum()<0)throw new NegocioException("El costo real no puede ser negativo.");m.setFechaResolucion(fecha);m.setCostoReal(dinero(costo));m.setEstado(EstadoMantenimiento.RESUELTO);restaurarInmueble(m);return m;}
 @Transactional public Mantenimiento cancelar(Long id){permisos.exigirGestion();Mantenimiento m=obtener(id);if(m.getEstado()!=EstadoMantenimiento.REPORTADO&&m.getEstado()!=EstadoMantenimiento.EN_PROCESO)throw new NegocioException("Solo se puede cancelar un mantenimiento reportado o en proceso.");if(m.getCuotaCargo()!=null){Cuota q=cuotas.findById(m.getCuotaCargo().getId()).orElseThrow(()->new NegocioException("No existe la cuota de cargo."));if(q.getMontoPagado().signum()>0)throw new NegocioException("No se puede cancelar: el cargo al arrendatario ya tiene pagos.");q.setEstado(EstadoCuota.ANULADA);}m.setEstado(EstadoMantenimiento.CANCELADO);restaurarInmueble(m);return m;}
 @Transactional public Cuota generarCargo(Long id,LocalDate vencimiento){permisos.exigirGestion();Mantenimiento m=obtener(id);if(m.getCuotaCargo()!=null)throw new NegocioException("El cargo al arrendatario ya fue generado para este mantenimiento.");if(m.getEstado()!=EstadoMantenimiento.RESUELTO)throw new NegocioException("El cargo se genera únicamente al resolver el mantenimiento.");if(m.getResponsablePago()!=ResponsablePago.ARRENDATARIO||m.getContrato()==null)throw new NegocioException("El mantenimiento no tiene un contrato a cargo del arrendatario.");if(vencimiento==null)throw new NegocioException("La fecha de vencimiento del cargo es obligatoria.");Cuota q=Cuota.builder().contrato(m.getContrato()).numero(Math.toIntExact(m.getId())).tipo(TipoCuota.OTRO).concepto("Reparación: "+m.getTitulo()).periodo(vencimiento.withDayOfMonth(1)).fechaVencimiento(vencimiento).montoCuota(dinero(m.getCostoReal())).montoPagado(BigDecimal.ZERO.setScale(2)).moraAcumulada(BigDecimal.ZERO.setScale(2)).moraCobrada(BigDecimal.ZERO.setScale(2)).moraCondonada(BigDecimal.ZERO.setScale(2)).estado(EstadoCuota.PENDIENTE).build();q=cuotas.save(q);m.setCuotaCargo(q);return q;}
 private void validarRegistro(Solicitud s){if(s.inmuebleId()==null||s.titulo()==null||s.titulo().isBlank()||s.categoria()==null||s.prioridad()==null||s.fechaReporte()==null)throw new NegocioException("Inmueble, título, categoría, prioridad y fecha de reporte son obligatorios.");if(s.fechaReporte().isAfter(LocalDate.now(clock)))throw new NegocioException("La fecha de reporte no puede ser futura.");if(s.costoEstimado()!=null&&s.costoEstimado().signum()<0)throw new NegocioException("Los costos no pueden ser negativos.");}
 private void restaurarInmueble(Mantenimiento m){if(m.isPusoInmuebleEnMantenimiento()&&m.getInmueble().getEstado()==EstadoInmueble.MANTENIMIENTO){m.getInmueble().setEstado(EstadoInmueble.DISPONIBLE);m.setPusoInmuebleEnMantenimiento(false);}}
 private Mantenimiento obtener(Long id){return mantenimientos.findById(id).orElseThrow(()->new NegocioException("El mantenimiento no existe."));}private Inmueble inmueble(Long id){return inmuebles.findById(id).orElseThrow(()->new NegocioException("El inmueble no existe."));}private Contrato contrato(Long id){return contratos.findById(id).orElseThrow(()->new NegocioException("El contrato no existe."));}private Contrato contratoVigente(Long id){return contratos.findByInmuebleIdOrderByFechaInicioDesc(id).stream().filter(c->c.getEstado()==EstadoContrato.VIGENTE).findFirst().orElse(null);}private void exigir(Mantenimiento m,EstadoMantenimiento e){if(m.getEstado()!=e)throw new NegocioException("La transición de "+m.getEstado()+" no está permitida.");}private static String texto(String s){return s==null||s.isBlank()?null:s.trim();}private static BigDecimal dineroNulo(BigDecimal n){return n==null?null:dinero(n);}private static BigDecimal dinero(BigDecimal n){return n.setScale(2,RoundingMode.HALF_UP);}
}
